import re
import numpy as np

# ==============================================================================
# Data structure for .vec files
# ==============================================================================
# The .vec file is generated by OMNeT++ simulations.
# Each .vec file contains time series data for various signals recorded during the simulation.
# The file .vec contains multiple vectors, each with a unique ID.
# Each vector is a series of (time, value) pairs.
#
# Saved in a dictionary like this:
#
#   vectors = {
#       1: {                                            <- key: vector ID
#           'module': 'HybridFusionNet.node[0].app[0]', <- which module emitted it
#           'name':   'rtt:vector',                     <- signal name
#           'times':  [31.19, 32.44, 33.89, ...],       <- list of times (seconds)
#           'values': [0.0104, 0.0112, 0.0108, ...],    <- list of values
#       },
#       
#       2: {
#           'module': 'HybridFusionNet.node[0].app[0]',
#           'name':   'pingTxSeq:vector',
#           'times':  [2.0, 3.12, 4.56, ...],           <- time of each ping sent
#           'values': [0, 1, 2, ...],                   <- ping sequence
#       },
#       ...
#   }
#
# ==============================================================================

def parse_vec(filepath):
    """
    Parse the .vec file from OMNeT++.
    The file has this structure:
        version 2/3
        run <run_name> ...
        vector <id> <module> <name> <type>     <- vector declaration
        <id> <time> <value>                    <- data point
        <id> <time> <value>                    <- data point
        ...
        vector <id2> <module2> <name2> <type>  <- vector declaration
        <id2> <time> <value>
        ...
    Returns a dictionary of vectors {id: {module, name, times, values}}.
    """
    # Dictionary of vectors: {id: {module, name, times, values}}
    vectors = {}
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            # Ignore empty lines and headers, attr appears both after 'run' and after each 'vector' (version 3)
            if not line or line.startswith('version') or line.startswith('run ') or line.startswith('attr '):
                continue
            
            # --- Vector declaration ---
            # Format: "vector 1 HybridFusionNet.node[0].app[0] rtt:vector ETV"
            if line.startswith('vector '):
                parts = line.split()
                # parts[0] = "vector"
                # parts[1] = numeric ID of the vector (e.g., "1")
                # parts[2] = module name
                # parts[3] = signal name
                # parts[4] = type (ETV = Event-Time-Value, we ignore it)
                vec_id = int(parts[1])
                vectors[vec_id] = {
                    'module': parts[2],
                    'name':   parts[3],
                    'times':  [], # List of times
                    'values': [], # List of values
                }
                continue
            
            # --- Data point of a vector declaration ---
            # Format: "1 31.190910 0.010390"
            # The first number is the ID of the vector to which this point belongs
            parts = line.split()
            if len(parts) >= 3:
                try:
                    vec_id = int(parts[0])       # ID of the vector
                    time   = float(parts[1])     # Simulation time
                    value  = float(parts[2])     # Signal value
                    # Add the point to the corresponding vector
                    if vec_id in vectors:
                        vectors[vec_id]['times'].append(time)
                        vectors[vec_id]['values'].append(value)
                except (ValueError, KeyError):
                    # If the line is not a valid data point, ignore it
                    pass

    # Convert the lists to numpy arrays for more efficient calculations
    for vec_id in vectors:
        vectors[vec_id]['times']  = np.array(vectors[vec_id]['times'])
        vectors[vec_id]['values'] = np.array(vectors[vec_id]['values'])
    return vectors

def find_vectors_by_name(vectors, name_pattern):
    """
    Find all vectors whose name matches a regex pattern.
    Examples:
        find_vectors_by_name(vectors, r'^rtt$')           -> finds only "rtt:vector"
        find_vectors_by_name(vectors, r'pingTxSeq')       -> finds "pingTxSeq:vector"
        find_vectors_by_name(vectors, r'lastActive')      -> finds "lastActiveInterface:vector"
    Returns a list of dictionaries with module, name, times, values.
    """
    results = []
    for vec_id, vec in vectors.items():
        # The name in the file includes ":vector" (e.g. "rtt:vector")
        # We search in the name without the suffix
        signal_name = vec['name'].replace(':vector', '')
        if re.search(name_pattern, signal_name):
            results.append(vec)
    return results

def extract_node_index(module_path):
    """
    Extracts the node index from the module path.
    Examples:
        "HybridFusionNet.node[3].app[0]" -> 3
        "HybridFusionNet.node[12].interfaceManager" -> 12
        "HybridFusionNet.server.app[0]" -> None (not a node)
    Returns the node index as an integer, or None if not found.
    """
    match = re.search(r'node\[(\d+)\]', module_path) # Search for "node[<index>]"
    return int(match.group(1)) if match else None

